package browse

import (
	"sort"
	"strings"

	"golang.org/x/text/cases"
)

// Kind is the search group an Entry belongs to; the two constants are the
// only values the builder supplies.
type Kind string

// The two search groups (design D7): series rank in their own bounded
// list, items in the other.
const (
	KindSeries Kind = "series"
	KindItem   Kind = "item"
)

// maxPerGroup pins the bounded 8+8 serving shape (design D7): at most
// eight series and eight items per query, ranked server-side.
const maxPerGroup = 8

// The match tiers, best first (design D2): a composed-name prefix outranks
// a composed-name substring, which outranks any unpicked-alternate hit.
// Alternates rank below BOTH composed tiers even when an alternate carries
// the prefix — the composed served name always wins its own entity's rank.
const (
	tierAlternate = iota
	tierSubstring
	tierPrefix
)

// Entry is one searchable entity as the builder supplies it: the composed
// served name plus the title walk's unpicked alternates. Names arrive
// already composed — the caller runs the composer (task 2.3's Deps), the
// index only folds for matching.
type Entry struct {
	// ID is the entity's store id, served back verbatim as the hit.
	ID string

	// LibraryID scopes the entry to its library — serving filters hits by
	// the caller's visible library ids.
	LibraryID string

	// Kind picks the hit group: KindSeries or KindItem.
	Kind Kind

	// DisplayName is the composed served name — the top match tier.
	DisplayName string

	// Alternates are the unpicked walk names (other languages, parser
	// title, dir_name_raw); any hit ranks below both composed tiers.
	Alternates []string
}

// foldSearch is the ONE shared match transform (design D2): Unicode
// casefold plus the ё→е map, applied at index-write AND query time —
// folding both sides is what makes the ё equivalence bidirectional
// («ёлка» matches "Елка" and "ЁЛКА" matches "елка").
func foldSearch(s string) string {
	return strings.ReplaceAll(caser.String(s), "ё", "е")
}

// caser is the shared Unicode casefolder behind foldSearch. A Caser is
// safe for concurrent use (the recs.go idiom).
var caser = cases.Fold()

// indexedEntry is a folded entry: the match forms are computed once at
// construction, never per query.
type indexedEntry struct {
	entry      Entry
	name       string
	alternates []string
}

// SearchIndex is the RAM search core: folded per-entity entries matched by
// the shared fold. Read-only after construction — Search is safe for
// concurrent use; rebuilds replace the whole index.
type SearchIndex struct {
	entries []indexedEntry
}

// NewSearchIndex builds the index over the supplied entries, folding every
// display name and alternate once at write time. The caller's slice is
// copied; later mutations of it are invisible to the index.
func NewSearchIndex(entries []Entry) *SearchIndex {
	ix := &SearchIndex{entries: make([]indexedEntry, 0, len(entries))}
	for _, e := range entries {
		alts := make([]string, len(e.Alternates))
		for i, a := range e.Alternates {
			alts[i] = foldSearch(a)
		}
		ix.entries = append(ix.entries, indexedEntry{
			entry:      e,
			name:       foldSearch(e.DisplayName),
			alternates: alts,
		})
	}
	return ix
}

// ranked is one matched entry with its tier — the sort key set for
// serving: tier desc, display name asc, id asc.
type ranked struct {
	id   string
	tier int
	name string
}

// Hits is the bounded answer: ranked id lists, at most maxPerGroup each.
// Both lists are non-nil — no match serves empty, not absent.
type Hits struct {
	Series []string
	Items  []string
}

// Search answers one query: fold it, scan the entries by tier, rank
// matches tier-desc then alphabetically, and bound each group at
// maxPerGroup. An empty (after fold) query matches nothing — browsing is
// the facets' job, not a wildcard.
func (ix *SearchIndex) Search(query string) Hits {
	q := foldSearch(query)
	var series, items []ranked
	if q != "" {
		for _, e := range ix.entries {
			tier := matchTier(e, q)
			if tier < 0 {
				continue
			}
			r := ranked{id: e.entry.ID, tier: tier, name: e.name}
			switch e.entry.Kind {
			case KindSeries:
				series = append(series, r)
			case KindItem:
				items = append(items, r)
			}
		}
	}
	return Hits{Series: topIDs(series), Items: topIDs(items)}
}

// matchTier ranks one entry against the folded query: composed prefix
// (best), composed substring, else any alternate hit (weakest); -1 is no
// match.
func matchTier(e indexedEntry, q string) int {
	switch {
	case strings.HasPrefix(e.name, q):
		return tierPrefix
	case strings.Contains(e.name, q):
		return tierSubstring
	}
	for _, alt := range e.alternates {
		if strings.Contains(alt, q) {
			return tierAlternate
		}
	}
	return -1
}

// topIDs ranks the matches — tier desc, display name asc, id asc — and
// bounds the list at maxPerGroup.
func topIDs(rs []ranked) []string {
	sort.Slice(rs, func(i, j int) bool {
		if rs[i].tier != rs[j].tier {
			return rs[i].tier > rs[j].tier
		}
		if rs[i].name != rs[j].name {
			return rs[i].name < rs[j].name
		}
		return rs[i].id < rs[j].id
	})
	if len(rs) > maxPerGroup {
		rs = rs[:maxPerGroup]
	}
	ids := make([]string, 0, len(rs))
	for _, r := range rs {
		ids = append(ids, r.id)
	}
	return ids
}
